def princes(c, lo, hi):
    out = []
    for v in range(lo, hi + 1):
        w = words('Num', c, v)
        for i, x in enumerate(w):
            if x == 'בן' and 0 < i < len(w) - 1 and w[i - 1] != 'אחד': out.append((w[i - 1], w[i + 1]))
    return out
def tribes(c, lo, hi):
    out = []
    for v in range(lo, hi + 1):
        w = words('Num', c, v)
        for i, x in enumerate(w):
            if x == 'למטה' and i + 1 < len(w): out.append(w[i + 1])
    return out
